INSERT INTO `announcements` (`id`, `title`, `body`, `priority`, `audience`, `published_by`, `published_at`, `created_at`, `updated_at`) VALUES
(1, 'Dashboard realtime sudah aktif', 'Nilai yang masuk akan langsung disiarkan ke leaderboard peserta.', 'high', 'all', 1, '2026-04-16 11:53:07', '2026-04-16 08:36:22', '2026-04-16 12:08:07'),
(2, 'Jadwal sesi pagi diperbarui', 'Registrasi peserta dimulai pukul 08.00 WIB dan sesi utama dimulai pukul 10.00 WIB.', 'normal', 'all', 1, '2026-04-16 11:08:07', '2026-04-16 08:36:22', '2026-04-16 12:08:07'),
(3, 'Pendaftaran e-MTQ dibuka 11 - 18 Mei 2026', 'Administrator kecamatan wajib melakukan pendaftaran online melalui e-MTQ dan melengkapi seluruh isian serta berkas scan administrasi.', 'high', 'all', 1, '2026-04-23 23:58:43', '2026-04-16 13:26:31', '2026-04-24 00:13:43'),
(4, 'Verifikasi dan masa sanggah peserta', 'Verifikasi tahap I berlangsung 19 - 25 Juni 2026, hasil diumumkan 26 Juni 2026, dan masa sanggah/penggantian peserta dibuka 9 - 11 Juni 2026.', 'normal', 'all', 1, '2026-04-23 23:13:43', '2026-04-16 13:26:31', '2026-04-24 00:13:43'),
(5, 'Official dapat mengajukan protes resmi', 'Sesuai juknis, official dapat mengajukan protes kepada pengawas dewan hakim paling cepat 5 jam setelah penampilan dengan bukti otentik.', 'normal', 'all', 1, '2026-04-23 22:13:43', '2026-04-16 13:26:31', '2026-04-24 00:13:43'),
(10, 'Verifikasi Tahap I berlangsung dari tanggal 19 Mei - 25 Mei 2026', 'Verifikasi Tahap I sedang berlangsung dari tanggal 19 Mei - 25 Mei 2026. Dimohonkan kepada seluruh Panitia dan Official Kecamatan selalu mengecek Halaman Data Peserta untuk hasil Verifikasi :D', 'high', 'all', 1, '2026-05-19 00:57:00', '2026-05-19 00:57:44', '2026-05-19 00:57:44');
